"use client";

import { useEffect, useRef, useState } from "react";

import sprite1x from "../resources/dino_game/images/default_100_percent/100-offline-sprite.png";
import sprite2x from "../resources/dino_game/images/default_200_percent/200-offline-sprite.png";

export default function DinoGame() {
  const [mode, setMode] = useState("auto");
  const [soundOn, setSoundOn] = useState(false);

  const gameContainerRef = useRef(null);
  const runnerRef = useRef(null);
  const soundOnRef = useRef(false);
  const originalPlaySoundRef = useRef(null);

  const autoPlayFrameRef = useRef(null);
  const restartTimeoutRef = useRef(null);

  const modeRef = useRef("auto");
  const jumpLockRef = useRef(false);
  const duckLockRef = useRef(false);

  /*
   * ============================================================
   * AUDIO RESOURCES
   * ============================================================
   *
   * MASUKKAN 3 BASE64 DARI COMPONENT KAMU YANG SEKARANG
   * KE SINI.
   *
   * Jangan mengubah bagian "data:audio/mpeg;base64,"
   */

  const SOUND_PRESS =
    "data:audio/mpeg;base64,";

  const SOUND_HIT =
    "data:audio/mpeg;base64,";

  const SOUND_REACHED =
    "data:audio/mpeg;base64,";

  /*
   * ============================================================
   * SEND KEY
   * ============================================================
   */

  const sendKey = (key, type) => {
    const keyCode =
      key === " "
        ? 32
        : key === "ArrowDown"
        ? 40
        : key === "ArrowUp"
        ? 38
        : 0;

    document.dispatchEvent(
      new KeyboardEvent(type, {
        key,
        code:
          key === " "
            ? "Space"
            : key === "ArrowDown"
            ? "ArrowDown"
            : key === "ArrowUp"
            ? "ArrowUp"
            : key,
        keyCode,
        which: keyCode,
        bubbles: true,
      })
    );
  };

  /*
   * ============================================================
   * JUMP
   * ============================================================
   */

  const jump = () => {
    if (jumpLockRef.current) return;

    jumpLockRef.current = true;

    sendKey(" ", "keydown");

    setTimeout(() => {
      sendKey(" ", "keyup");
    }, 80);

    setTimeout(() => {
      jumpLockRef.current = false;
    }, 350);
  };

  /*
   * ============================================================
   * DUCK
   * ============================================================
   */

  const duck = (active) => {
    if (active) {
      if (duckLockRef.current) return;

      duckLockRef.current = true;
      sendKey("ArrowDown", "keydown");

      return;
    }

    if (!duckLockRef.current) return;

    duckLockRef.current = false;
    sendKey("ArrowDown", "keyup");
  };

  /*
   * ============================================================
   * AUTO PLAY
   * ============================================================
   */

  const runAutoPlay = () => {
    const runner = runnerRef.current;

    if (!runner || modeRef.current !== "auto") {
      return;
    }

    /*
     * ----------------------------------------------------------
     * GAME CRASHED
     * ----------------------------------------------------------
     */

    if (runner.crashed) {
      duck(false);

      if (!restartTimeoutRef.current) {
        restartTimeoutRef.current = setTimeout(() => {
          restartTimeoutRef.current = null;

          if (
            runnerRef.current === runner &&
            modeRef.current === "auto" &&
            runner.crashed
          ) {
            /*
             * Runner bawaan akan menangani Space setelah crash
             * untuk memulai kembali.
             */
            jump();
          }
        }, 800);
      }

      return;
    }

    /*
     * ----------------------------------------------------------
     * GAME BELUM MULAI
     * ----------------------------------------------------------
     */

    if (!runner.playing) {
      jump();
      return;
    }

    /*
     * ----------------------------------------------------------
     * AMBIL DINOSAUR
     * ----------------------------------------------------------
     */

    const trex = runner.tRex;

    if (!trex) {
      return;
    }

    /*
     * ----------------------------------------------------------
     * AMBIL OBSTACLE
     * ----------------------------------------------------------
     */

    const obstacles = runner.horizon?.obstacles || [];

    if (obstacles.length === 0) {
      duck(false);
      return;
    }

    /*
     * Cari obstacle pertama yang masih berada
     * di depan Dino.
     */

    const obstacle = obstacles.find(
      (item) => item.xPos + item.width > trex.xPos
    );

    if (!obstacle) {
      duck(false);
      return;
    }

    /*
     * Jarak obstacle dari posisi Dino.
     */

    const distance = obstacle.xPos - trex.xPos;

    /*
     * ----------------------------------------------------------
     * REACTION DISTANCE
     * ----------------------------------------------------------
     *
     * Semakin cepat game, semakin jauh AI harus bereaksi.
     */

    const reactionDistance = Math.max(
      100,
      runner.currentSpeed * 8
    );

    /*
     * ----------------------------------------------------------
     * FLYING OBSTACLE
     * ----------------------------------------------------------
     *
     * Pterodactyl mempunyai posisi Y berbeda dengan
     * obstacle yang berada di tanah.
     */

    const isFlyingObstacle =
      obstacle.yPos < trex.yPos - 10;

    if (isFlyingObstacle) {
      const duckDistance = Math.max(
        80,
        runner.currentSpeed * 5
      );

      /*
       * Flying obstacle yang cukup rendah → duck.
       */

      if (
        distance > 0 &&
        distance < duckDistance &&
        obstacle.yPos > trex.yPos - 45
      ) {
        duck(true);
      } else {
        duck(false);
      }

      return;
    }

    /*
     * ----------------------------------------------------------
     * GROUND OBSTACLE
     * ----------------------------------------------------------
     */

    duck(false);

    if (
      distance > 0 &&
      distance < reactionDistance
    ) {
      jump();
    }
  };

  /*
   * ============================================================
   * CHANGE MODE
   * ============================================================
   */

  const changeMode = (newMode) => {
    modeRef.current = newMode;
    setMode(newMode);

    duck(false);

    /*
     * Hapus timeout restart jika user pindah mode.
     */

    if (restartTimeoutRef.current) {
      clearTimeout(restartTimeoutRef.current);
      restartTimeoutRef.current = null;
    }

    /*
     * Ketika kembali ke Auto, langsung mulai/restart.
     */

    if (newMode === "auto") {
      setTimeout(() => {
        if (modeRef.current === "auto") {
          jump();
        }
      }, 100);
    }
  };

  /*
 * ============================================================
 * SOUND TOGGLE
 * ============================================================
 */
  const toggleSound = () => {
    const runner = runnerRef.current;

    if (!runner) return;

    const nextSoundState = !soundOnRef.current;

    soundOnRef.current = nextSoundState;
    setSoundOn(nextSoundState);

    /*
    * Simpan fungsi playSound asli hanya sekali.
    */
    if (!originalPlaySoundRef.current && typeof runner.playSound === "function") {
      originalPlaySoundRef.current = runner.playSound.bind(runner);
    }

    /*
    * SFX ON
    */
    if (nextSoundState) {
      if (originalPlaySoundRef.current) {
        runner.playSound = originalPlaySoundRef.current;
      }
    }

    /*
    * SFX OFF
    */
    else {
      runner.playSound = () => {};
    }
  };

  /*
   * ============================================================
   * INITIALIZE GAME
   * ============================================================
   */

  useEffect(() => {
    let mounted = true;

    const createAudioResources = () => {
      /*
       * Jangan menggunakan <template> di JSX.
       * Template dibuat langsung di browser untuk menghindari
       * hydration mismatch dari Next.js.
       */

      const template = document.createElement("template");

      template.id = "audio-resources";

      const press = document.createElement("audio");
      press.id = "offline-sound-press";
      press.src = SOUND_PRESS;

      const hit = document.createElement("audio");
      hit.id = "offline-sound-hit";
      hit.src = SOUND_HIT;

      const reached = document.createElement("audio");
      reached.id = "offline-sound-reached";
      reached.src = SOUND_REACHED;

      template.content.appendChild(press);
      template.content.appendChild(hit);
      template.content.appendChild(reached);

      document.body.appendChild(template);

      return template;
    };

    const createImageResources = () => {
      const container = document.createElement("div");

      container.id = "offline-resources";
      container.style.display = "none";

      const image1x = document.createElement("img");

      image1x.id = "offline-resources-1x";
      image1x.src = sprite1x.src;
      image1x.alt = "";

      const image2x = document.createElement("img");

      image2x.id = "offline-resources-2x";
      image2x.src = sprite2x.src;
      image2x.alt = "";

      container.appendChild(image1x);
      container.appendChild(image2x);

      document.body.appendChild(container);

      return container;
    };

    const initGame = async () => {
      if (!gameContainerRef.current) return;

      let audioTemplate = null;
      let imageResources = null;

      try {
        /*
         * Buat resource DOM terlebih dahulu.
         */

        audioTemplate = createAudioResources();
        imageResources = createImageResources();

        /*
         * Load Runner.
         */

        const { Runner } = await import(
          "../resources/dino_game/offline.js"
        );

        if (
          !mounted ||
          !gameContainerRef.current
        ) {
          return;
        }

        /*
         * Pastikan mode awal AUTO.
         */

        modeRef.current = "auto";

        /*
         * Jalankan game.
         */

        runnerRef.current = new Runner(
        gameContainerRef.current
      );

      /*
      * ==========================================================
      * DEFAULT SFX OFF
      * ==========================================================
      *
      * Simpan fungsi playSound asli, kemudian override
      * dengan fungsi kosong agar game tidak mengeluarkan suara.
      */

      if (typeof runnerRef.current.playSound === "function") {
        originalPlaySoundRef.current =
          runnerRef.current.playSound.bind(runnerRef.current);

        runnerRef.current.playSound = () => {};
      }

      soundOnRef.current = false;

        /*
         * ======================================================
         * AUTO PLAY LOOP
         * ======================================================
         */

        const autoLoop = () => {
          if (!mounted) return;

          if (modeRef.current === "auto") {
            runAutoPlay();
          }

          autoPlayFrameRef.current =
            requestAnimationFrame(autoLoop);
        };

        autoPlayFrameRef.current =
          requestAnimationFrame(autoLoop);
      } catch (error) {
        console.error(
          "Failed to load T-Rex Runner:",
          error
        );
      }
    };

    initGame();

    /*
     * ==========================================================
     * CLEANUP
     * ==========================================================
     */

    return () => {
      mounted = false;

      if (autoPlayFrameRef.current) {
        cancelAnimationFrame(
          autoPlayFrameRef.current
        );

        autoPlayFrameRef.current = null;
      }

      if (restartTimeoutRef.current) {
        clearTimeout(
          restartTimeoutRef.current
        );

        restartTimeoutRef.current = null;
      }

      duck(false);

      if (runnerRef.current) {
        try {
          runnerRef.current.destroy();
        } catch (error) {
          console.warn(
            "Failed to destroy T-Rex Runner:",
            error
          );
        }

        runnerRef.current = null;
      }

      const audioTemplate =
        document.getElementById(
          "audio-resources"
        );

      if (audioTemplate) {
        audioTemplate.remove();
      }

      const imageResources =
        document.getElementById(
          "offline-resources"
        );

      if (imageResources) {
        imageResources.remove();
      }
    };
  }, []);

  /*
   * ============================================================
   * RENDER
   * ============================================================
   */

  return (
    <section className="w-full py-20 dark:bg-neutral-950">
      <div className="mx-auto w-full max-w-6xl px-6">

        {/* Heading */}
        <div className="mb-8">
          <p className="mb-2 text-sm font-medium uppercase tracking-[0.2em] text-gray-500 dark:text-gray-400">
            Just for fun
          </p>

          <h2 className="text-3xl font-semibold tracking-tight text-gray-900 dark:text-white">
            T-Rex Runner
          </h2>

          {/* Controls */}
        <div className="flex flex-wrap items-center justify-between gap-3">

          <div className="text-xs text-gray-400">
            {mode === "auto" ? (
              <span>
                AUTO PLAY — Click the game to play
              </span>
            ) : (
              <span>
                MANUAL — SPACE / ↑ to jump
              </span>
            )}
          </div>
          <div className="flex items-center">
            <button
                type="button"
                onClick={toggleSound}
                aria-label={soundOn ? "Mute sound" : "Enable sound"}
                className="rounded-md px-2 py-1.5 text-gray-500 transition hover:text-gray-900 dark:text-gray-400 dark:hover:text-white"
              >
                {soundOn ? (
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="18"
                    height="18"
                    fill="currentColor"
                    className="bi bi-volume-up"
                    viewBox="0 0 16 16"
                  >
                    <path d="M11.536 14.01A8.47 8.47 0 0 0 14.026 8a8.47 8.47 0 0 0-2.49-6.01l-.708.707A7.48 7.48 0 0 1 13.025 8c0 2.071-.84 3.946-2.197 5.303z" />
                    <path d="M10.121 12.596A6.48 6.48 0 0 0 12.025 8a6.48 6.48 0 0 0-1.904-4.596l-.707.707A5.48 5.48 0 0 1 11.025 8a5.48 5.48 0 0 1-1.61 3.89z" />
                    <path d="M10.025 8a4.5 4.5 0 0 1-1.318 3.182L8 10.475A3.5 3.5 0 0 0 9.025 8c0-.966-.392-1.841-1.025-2.475l.707-.707A4.5 4.5 0 0 1 10.025 8M7 4a.5.5 0 0 0-.812-.39L3.825 5.5H1.5A.5.5 0 0 0 1 6v4a.5.5 0 0 0 .5.5h2.325l2.363 1.89A.5.5 0 0 0 7 12zM4.312 6.39 6 5.04v5.92L4.312 9.61A.5.5 0 0 0 4 9.5H2v-3h2a.5.5 0 0 0 .312-.11" />
                  </svg>
                ) : (
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="18"
                    height="18"
                    fill="currentColor"
                    className="bi bi-volume-mute"
                    viewBox="0 0 16 16"
                  >
                    <path d="M6.717 3.55A.5.5 0 0 1 7 4v8a.5.5 0 0 1-.812.39L3.825 10.5H1.5A.5.5 0 0 1 1 10V6a.5.5 0 0 1 .5-.5h2.325l2.363-1.89a.5.5 0 0 1 .529-.06M6 5.04 4.312 6.39A.5.5 0 0 1 4 6.5H2v3h2a.5.5 0 0 1 .312.11L6 10.96zm7.854.606a.5.5 0 0 1 0 .708L12.207 8l1.647 1.646a.5.5 0 0 1-.708.708L11.5 8.707l-1.646 1.647a.5.5 0 0 1-.708-.708L10.793 8 9.146 6.354a.5.5 0 1 1 .708-.708L11.5 7.293l1.646-1.647a.5.5 0 0 1 .708 0" />
                  </svg>
                )}
              </button>
            <div className="flex items-center gap-1 rounded-lg border border-gray-200 bg-gray-50 p-1 dark:border-slate-700 dark:bg-neutral-950">
              <button
                type="button"
                onClick={() => changeMode("auto")}
                className={`rounded-md px-3 py-1.5 text-xs font-medium transition ${
                  mode === "auto"
                    ? "bg-gray-900 text-white dark:bg-white dark:text-gray-900"
                    : "text-gray-500 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white"
                }`}
              >
                Auto
              </button>

              <button
                type="button"
                onClick={() => changeMode("manual")}
                className={`rounded-md px-3 py-1.5 text-xs font-medium transition ${
                  mode === "manual"
                    ? "bg-gray-900 text-white dark:bg-white dark:text-gray-900"
                    : "text-gray-500 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white"
                }`}
              >
                Manual
              </button>

            </div>
          </div>
          </div>
          
        </div>

        {/* Game */}
        <div
          ref={gameContainerRef}
          onClick={(event) => {
            /*
             * Kalau sedang AUTO dan game diklik,
             * pindah ke MANUAL.
             */

            if (modeRef.current === "auto") {
              event.stopPropagation();
              changeMode("manual");
            }
          }}
          className="trex-game relative w-full overflow-hidden bg-white dark:bg-neutral-950"
        />

      </div>
    </section>
  );
}